const PDFW: Lib = ["pdf.worker-3.11.174.min.js", "pdfjs-dist@3.11.174/legacy/build/pdf.worker.min.js", "sha384-sS8B4COeBqzQV9DaPpp5cbpF+xz2jPcFbN3L8FL3/dx0RMC6WLUwTUOFm0iFb1lw"];
