export const officeKind = (name: string): OfficeKind | null => {
  const e = name.split(".").pop()?.toLowerCase() ?? "";
  return e === "docx" ? "docx" : e === "xlsx" || e === "xlsm" ? "xlsx" : e === "csv" || e === "tsv" ? "csv" : e === "pptx" ? "pptx" : e === "pdf" ? "pdf" : null;
};

